import AchievementService from '../achievement_service';import { FirebaseFirestore } from '@firebase/firestore';jest.mock('@firebase/firestore');describe('AchievementService', () => {  let achievementService;  let mockFirestore;  beforeEach(() => {    mockFirestore = {      collection: jest.fn().mockReturnThis(),      doc: jest.fn().mockReturnThis(),      set: jest.fn(),      update: jest.fn(),      where: jest.fn().mockReturnThis(),      get: jest.fn(),      runTransaction: jest.fn(),    };    FirebaseFirestore.mockImplementation(() => mockFirestore);    achievementService = new AchievementService();  });  describe('unlockAchievement', () => {    it('unlocks achievement and updates user', async () => {      await achievementService.unlockAchievement('user123', 'ach1');      expect(mockFirestore.collection).toHaveBeenCalledWith('achievements');      expect(mockFirestore.doc).toHaveBeenCalledWith('user123-ach1');      expect(mockFirestore.set).toHaveBeenCalledWith({        userId: 'user123',        achievementId: 'ach1',        unlockedAt: expect.any(Date),        claimed: false,      });      expect(mockFirestore.collection).toHaveBeenCalledWith('users');      expect(mockFirestore.doc).toHaveBeenCalledWith('user123');      expect(mockFirestore.update).toHaveBeenCalled();    });  });  describe('syncWithServer', () => {    it('syncs achievements with server', async () => {      const mockSnapshot = {        docs: [          { reference: { delete: jest.fn() } },        ],      };      mockFirestore.get.mockResolvedValue(mockSnapshot);      await achievementService.syncWithServer('user123');      expect(mockFirestore.collection).toHaveBeenCalledWith('achievements');      expect(mockFirestore.where).toHaveBeenCalledWith('userId', 'isEqualTo', 'user123');      expect(mockFirestore.get).toHaveBeenCalled();      expect(mockSnapshot.docs[0].reference.delete).toHaveBeenCalled();    });  });  describe('getAchievementName', () => {    it('returns achievement name', () => {      const data = { name: 'Test Achievement' };      expect(achievementService.getAchievementName(data)).toBe('Test Achievement');    });    it('throws error when data is null', () => {      expect(() => achievementService.getAchievementName(null)).toThrow();    });  });});